#include <stdio.h>
int main(void) {
    double f = 1e9;      /* 主频 1 GHz = 1e9 Hz */
    double ic = 5e8;     /* 程序指令数 = 5 亿 */
    double cpi = 1.5;    /* 平均 CPI */
    double t = ic * cpi / f;   /* CPU 时间（秒） */
    printf("主频 = 1000 MHz\n");
    printf("指令数 = 500000000\n");
    printf("平均CPI = 1.50\n");
    printf("CPU 时间 = 指令数 * CPI / 主频 = %.3f s (%.1f ms)\n", t, t * 1000);
    return 0;
}
